import numpy as np
import pandas as pd
from datetime import datetime, timedelta
import zoneinfo
from dateutil.relativedelta import relativedelta
import calendar

def r_time_add(time, periods=None, roll_month="preday", roll_dst=("pre", "post"), **kwargs):
    """
    Implementation of the logic in the timechange package's time_add.
    """
    if isinstance(time, (list, np.ndarray, pd.Series, pd.Index)):
        t_arr = np.asarray(time, dtype=float)
    else:
        t_arr = np.array([float(time)], dtype=float)

    if t_arr.size == 0:
        return t_arr

    if periods is None:
        periods = {}

    n = t_arr.size

    def get_val(name):
        val = periods.get(name, 0)
        if isinstance(val, (list, np.ndarray, pd.Series)):
            val = np.asarray(val)
            if val.size != 1 and val.size != n:
                raise ValueError(f"time_add: Incompatible size of '{name}' vector")
            return val if val.size == n else np.full(n, val[0])
        return np.full(n, val)

    y = get_val("year") if "year" in periods else None
    m = get_val("month") if "month" in periods else None
    w = get_val("week") if "week" in periods else None
    d = get_val("day") if "day" in periods else None
    h = get_val("hour") if "hour" in periods else None
    mi = get_val("minute") if "minute" in periods else None
    s = get_val("second") if "second" in periods else None

    results = []
    for i in range(n):
        t_val = t_arr[i]
        if np.isnan(t_val):
            results.append(np.nan)
            continue

        # Convert POSIXct to civil time in UTC
        ts = pd.Timestamp(t_val, unit='s', tz='UTC')
        cy, cm, cd = ts.year, ts.month, ts.day
        tH, tM, tS = ts.hour, ts.minute, ts.second
        rem = t_val - np.floor(t_val)

        if y is not None:
            cy += int(y[i])

        # Month logic
        target_date = datetime(cy, 1, 1) + relativedelta(months=cm - 1)
        if m is not None:
            target_date += relativedelta(months=int(m[i]))

        cy, cm = target_date.year, target_date.month

        original_day = cd
        last_day_of_target = calendar.monthrange(cy, cm)[1]

        add_my_hms = True
        if original_day > last_day_of_target:
            if roll_month == "preday":
                cd = last_day_of_target
            elif roll_month == "boundary":
                cd = 1
                add_my_hms = False
            elif roll_month == "postday":
                target_dt = datetime(cy, cm, 1)
                next_month = target_dt + relativedelta(months=1)
                cy, cm, cd = next_month.year, next_month.month, next_month.day
            elif roll_month == "full":
                res_date = datetime(cy, cm, 1) + timedelta(days=original_day - 1)
                cy, cm, cd = res_date.year, res_date.month, res_date.day
            elif roll_month == "NA":
                results.append(np.nan)
                continue
            else: # NAym
                cd = original_day
        else:
            cd = original_day

        if w is not None:
            res_date = datetime(cy, cm, cd) + timedelta(weeks=int(w[i]))
            cy, cm, cd = res_date.year, res_date.month, res_date.day

        if d is not None:
            res_date = datetime(cy, cm, cd) + timedelta(days=int(d[i]))
            cy, cm, cd = res_date.year, res_date.month, res_date.day

        final_dt = datetime(cy, cm, cd)
        if add_my_hms:
            final_dt = final_dt.replace(hour=tH, minute=tM, second=tS)

        if h is not None:
            final_dt += timedelta(hours=int(h[i]))
        if mi is not None:
            final_dt += timedelta(minutes=int(mi[i]))
        if s is not None:
            S_int = int(np.floor(s[i]))
            final_dt += timedelta(seconds=S_int)
            rem += (s[i] - S_int)

        dt_utc = final_dt.replace(tzinfo=zoneinfo.ZoneInfo("UTC"))
        results.append(dt_utc.timestamp() + rem)

    return np.array(results, dtype=float)

def r_time_subtract(time, periods=None, year=None, month=None, week=None, 
                    day=None, hour=None, minute=None, second=None, 
                    roll_month="preday", roll_dst=("pre", "post"), **kwargs):

    if isinstance(roll_month, (np.ndarray, np.generic)):
        roll_month = str(roll_month)

    # Handle time input and track if it's a scalar
    is_scalar = not isinstance(time, (np.ndarray, pd.Series, pd.Index, list))

    if is_scalar:
        if pd.isnull(time):
            return np.nan
        t_arr = np.array([pd.Timestamp(time).timestamp()], dtype=float)
    elif len(time) == 0:
        return time
    else:
        t_arr = np.array([pd.Timestamp(x).timestamp() if pd.notnull(x) else np.nan for x in time], dtype=float)

    dots = kwargs
    if dots:
        cleaned_dots = {k.rstrip('s') if k.endswith('s') else k: v for k, v in dots.items()}
        if periods is None:
            periods = cleaned_dots
        elif isinstance(periods, dict):
            periods = {**periods, **cleaned_dots}
        else:
            raise TypeError("character periods are not implemented yet")

    if periods is None:
        periods = {}

    final_periods = {}
    for k, v in periods.items():
        if v is not None:
            final_periods[k] = -np.array(v) if isinstance(v, (np.ndarray, list)) else -v

    prds = {
        "year": year, "month": month, "week": week, "day": day,
        "hour": hour, "minute": minute, "second": second
    }

    for nm, val in prds.items():
        if val is not None:
            if nm not in final_periods:
                final_periods[nm] = -val
            else:
                final_periods[nm] = final_periods[nm] - val

    res_floats = r_time_add(t_arr, periods=final_periods, roll_month=roll_month, roll_dst=roll_dst)

    def to_timestamp(val):
        if np.isnan(val):
            return np.nan
        return pd.Timestamp(val, unit='s', tz='UTC').tz_localize(None)

    if is_scalar:
        return to_timestamp(res_floats[0])

    return np.array([to_timestamp(v) for v in res_floats])
